// Nhận tham số từ L02 hoặc Webhook kiểm thử
const item = $input.first()?.json || {};
const data = item.body || item;

const ticketId = data.ticket_id ?? data.ticketId ?? null;
const message  = data.message  ?? data.text ?? data.content ?? '';
const messageId = data.message_id ?? data.messageId ?? null;
const intent   = data.intent ?? 'ORDER_STATUS';
const customerId = data.customer_id ?? data.customerId ?? null;

// Validation bắt buộc
const errors = [];
if (!ticketId) errors.push('Thiếu ticket_id');
if (!message && !customerId) errors.push('Thiếu message hoặc customerId');

if (errors.length > 0) {
  throw new Error('[L13_Order_Status] Lỗi đầu vào: ' + errors.join(', '));
}

return [{
  json: {
    ticket_id:   Number(ticketId),
    message:     String(message),
    message_id:  messageId ? Number(messageId) : null,
    intent:      String(intent),
    customer_id: customerId ? Number(customerId) : null
  }
}];

// Kiểm tra số đơn tìm được
const ticketMeta = $('MySQL – Lấy ticket và khách').first().json;
const recentOrders = $input.all().map(i => i.json);

if (recentOrders.length === 0) {
  // Không tìm thấy đơn nào
  return [{
    json: {
      action: 'ASK_ORDER_CODE',
      reply_text: 'Xin chào! Chúng tôi chưa tìm thấy đơn hàng nào liên kết với tài khoản của bạn. Bạn vui lòng cung cấp mã đơn hàng (ví dụ: DH-1001) để chúng tôi hỗ trợ nhé?',
      ticket_id: ticketMeta.ticket_id,
      channel: ticketMeta.channel,
      customer_telegram_id: ticketMeta.customer_telegram_id
    }
  }];
}

if (recentOrders.length === 1) {
  // Đúng 1 đơn, dùng luôn
  return [{
    json: {
      action: 'USE_SINGLE_ORDER',
      order_code: recentOrders[0].order_code,
      ...ticketMeta
    }
  }];
}

// Nhiều đơn, hỏi khách chọn
const orderList = recentOrders.map(o =>
  `• ${o.order_code} – ${o.status} (${new Date(o.ordered_at).toLocaleDateString('vi-VN')})`
).join('\n');

return [{
  json: {
    action: 'ASK_WHICH_ORDER',
    reply_text: `Chúng tôi tìm thấy ${recentOrders.length} đơn hàng gần đây của bạn:\n${orderList}\n\nBạn muốn tra cứu đơn hàng nào? Vui lòng cho biết mã đơn.`,
    ticket_id: ticketMeta.ticket_id,
    channel: ticketMeta.channel,
    customer_telegram_id: ticketMeta.customer_telegram_id
  }
}];

// Chuẩn bị payload xác minh chủ đơn
const ticketMeta = $('MySQL – Lấy ticket và khách').first().json;
const extracted  = $('Information Extractor – Trích mã đơn').first().json;
const params     = $('Code – Nhận tham số').first().json;

// Normalize mã đơn: DH1001 -> DH-1001
let orderCode = (extracted.orderCode || '').trim().toUpperCase();
if (/^DH\d+$/i.test(orderCode)) {
  orderCode = 'DH-' + orderCode.replace(/^DH/i, '');
}

return [{
  json: {
    orderCode:  orderCode,
    customerId: ticketMeta.customer_id,
    phone:      extracted.phone || ticketMeta.customer_phone || null,
    email:      ticketMeta.customer_email || null,
    ticketId:   params.ticket_id,
    // Pass through metadata
    ticket_id:  params.ticket_id,
    channel:    ticketMeta.channel,
    customer_name:        ticketMeta.customer_name,
    customer_telegram_id: ticketMeta.customer_telegram_id,
    customer_email:       ticketMeta.customer_email,
    preferred_language:   ticketMeta.preferred_language || 'vi'
  }
}];

// Trả lời trung tính khi không khớp chủ đơn
const ticketMeta = $('MySQL – Lấy ticket và khách').first().json;
return [{
  json: {
    reply_text: 'Xin lỗi, chúng tôi không thể xác nhận thông tin đơn hàng này. Vui lòng cung cấp số điện thoại hoặc email đã sử dụng khi đặt hàng để chúng tôi hỗ trợ bạn.',
    ticket_id:  ticketMeta.ticket_id,
    channel:    ticketMeta.channel,
    customer_telegram_id: ticketMeta.customer_telegram_id
  }
}];

// Gộp trạng thái nội bộ và vận chuyển
const verifyData = $('HTTP Request – POST /api/n8n/orders/verify').first().json;
const ticketMeta = $('MySQL – Lấy ticket và khách').first().json;

// Thử lấy tracking data (có thể thất bại)
let trackingEvent = null;
try {
  const trackResp = $('HTTP Request – Tra cứu vận đơn').first()?.json;
  if (trackResp && trackResp.status === 'success' && trackResp.data) {
    const events = Array.isArray(trackResp.data) ? trackResp.data : [trackResp.data];
    trackingEvent = events[events.length - 1]; // sự kiện mới nhất
  }
} catch (e) {}

// Tính late_days khi đơn SHIPPING
let lateDays = 0;
const STANDARD_SHIP_DAYS = 5;
if (verifyData.status === 'SHIPPING' && verifyData.orderedAt) {
  const orderedMs = new Date(verifyData.orderedAt).getTime();
  const nowMs = Date.now();
  const daysPassed = Math.floor((nowMs - orderedMs) / (1000 * 60 * 60 * 24));
  lateDays = Math.max(0, daysPassed - STANDARD_SHIP_DAYS);
}

return [{
  json: {
    ...verifyData,
    tracking_event: trackingEvent,
    late_days:      lateDays,
    ticket_id:      ticketMeta.ticket_id,
    channel:        ticketMeta.channel,
    customer_name:  ticketMeta.customer_name || 'Quý khách',
    customer_telegram_id: ticketMeta.customer_telegram_id,
    customer_email:       ticketMeta.customer_email,
    preferred_language:   ticketMeta.preferred_language || 'vi'
  }
}];

