// Chuẩn bị payload gửi đa kênh qua L15_Dispatcher
const orderData  = $('Code – Gộp trạng thái').first().json;
const aiText     = $input.first()?.json?.text || orderData.reason || 'Vui lòng liên hệ hỗ trợ để biết thêm thông tin về đơn hàng.';

return [{
  json: {
    ticket_id:  orderData.ticket_id,
    channel:    orderData.channel,
    reply_text: aiText,
    customer_telegram_id: orderData.customer_telegram_id,
    customer_email:       orderData.customer_email,
    customer_name:        orderData.customer_name,
    needs_translation:    (orderData.preferred_language || 'vi') !== 'vi',
    target_language:      orderData.preferred_language || 'vi',
    // Truyền late_days để bước sau kiểm tra
    late_days:            orderData.late_days || 0,
    order_code:           orderData.orderCode,
    order_status:         orderData.status
  }
}];

// Ticket hợp lệ nhưng AI bị khóa – trả thông báo nhẹ
const params = $('Code – Nhận tham số').first().json;
return [{
  json: {
    skipped: true,
    reason: 'ai_locked hoặc ticket không tồn tại',
    ticket_id: params.ticket_id
  }
}];

// Đơn không tìm thấy – soạn thông báo
const ticketMeta = $('MySQL – Lấy ticket và khách').first().json;
return [{
  json: {
    reply_text: 'Xin lỗi, chúng tôi không tìm thấy đơn hàng bạn đề cập trong hệ thống. Bạn vui lòng kiểm tra lại mã đơn hàng hoặc liên hệ bộ phận hỗ trợ để được giúp đỡ.',
    ticket_id:  ticketMeta.ticket_id,
    channel:    ticketMeta.channel,
    customer_telegram_id: ticketMeta.customer_telegram_id
  }
}];
